import java.util.*;

class Solution {
  private int[] nums;
  private int[][] memo;
  private int[][] choice;

  public int[] findPermutation(int[] nums) {
    this.nums = nums;
    int n = nums.length;
    memo = new int[1 << n][n];
    choice = new int[1 << n][n];
    for (int[] row : memo) Arrays.fill(row, -1);
    cost(1, 0);
    int[] result = new int[n];
    int mask = 1, last = 0;
    result[0] = 0;
    for (int i = 1; i < n; i++) {
      int next = choice[mask][last];
      result[i] = next;
      mask |= 1 << next;
      last = next;
    }
    return result;
  }

  private int cost(int mask, int last) {
    if (mask == (1 << nums.length) - 1) return Math.abs(last - nums[0]);
    if (memo[mask][last] != -1) return memo[mask][last];
    int best = Integer.MAX_VALUE;
    for (int next = 1; next < nums.length; next++) {
      if ((mask & (1 << next)) == 0) {
        int candidate = Math.abs(last - nums[next]) + cost(mask | (1 << next), next);
        if (candidate < best) {
          best = candidate;
          choice[mask][last] = next;
        }
      }
    }
    return memo[mask][last] = best;
  }
}
